import test from 'node:test';import assert from 'node:assert/strict';
import {serialize,restore,createArea} from '../engine.js';import {setModule} from '../rules.js';
import {foundationFixture,foundationSteps,foundationSave,foundationContext as ctx} from '../scripts/foundation-scenarios.mjs';
import {peopleTick} from '../modules/people.js';import {prepareFoundation} from '../modules/foundation.js';
import {actualService} from '../modules/service-access.js';import {productionSources,goodsBalance} from '../modules/goods.js';import {initializeFacades} from '../facades.js';
const exact=f=>{const raw=foundationSave(f);assert.equal(serialize(restore(raw)),raw);return raw;};
test('four real work acts turn one stable parcel into one poor settlement, consuming owned raw/tool/food without new residents',()=>{
 const f=foundationFixture(),{s,a,builder,g,source}=f,area=a.id,people=Object.keys(s.people),food=g.cargo.food,balance=source.civic.food;assert.equal(a.civic,undefined);foundationSteps(f,4);const r=a.foundation,town=a.foundedSettlement;assert.equal(r.status,'done');assert.equal(r.progress,4);assert.equal(r.steps.length,4);assert.equal(r.material.consumed,4);assert.equal(r.material.remaining,0);assert.equal(builder.goodsRawCargo.quantity,0);assert.equal(builder.agenda.tools,0);assert.equal(r.tool.state,'installed');assert.equal(a.id,area);assert.equal(a.type,'village');assert.equal(g.status,'founded');assert.equal(a.civic.food,food-4);assert.equal(g.cargo.food,0);assert.equal(source.civic.food,balance);assert.equal(a.civic.treasury,0);assert.equal(a.civic.tools,0);assert.equal(a.civic.medicine,0);assert.equal(productionSources(s,a).materials.stock,0);assert.equal(productionSources(s,a).field.stock,0);assert.equal(productionSources(s,a).field.capacity,0);assert.deepEqual(Object.keys(s.people),people);assert.equal(a.facades.profiles.length,1);assert.equal(a.objects.filter(o=>o.foundation===r.id).length,1);assert.ok(town.founders.every(id=>s.people[id].home===area&&r.previousHomes[id]===source.id));assert.equal(actualService(s,a,'food').available,true);assert.equal(actualService(s,a,'employment').available,false);assert.equal(goodsBalance(a,'food').difference,0);exact(f);
});
test('illness interrupts the builder without losing paid progress, and another present capable founder resumes from the saved step',()=>{
 const f=foundationSteps(foundationFixture(),1),{s,a,builder,leader}=f;assert.equal(a.foundation.progress,1);assert.ok(prepareFoundation(s,builder));builder.ailment='лихорадка';builder.health=40;leader.needs.sleeping=true;foundationSteps(f,1);assert.equal(a.foundation.progress,1);assert.equal(a.foundation.pause.reason,'health');assert.equal(builder.goodsRawCargo.quantity,0);const raw=exact(f),copy=restore(raw);leader.needs.sleeping=false;copy.people[leader.id].needs.sleeping=false;for(const w of [s,copy])for(let i=0;i<3;i++){w.tick=Math.floor(w.tick/8)*8+8;peopleTick(w,ctx);}assert.equal(serialize(s),serialize(copy));assert.equal(a.foundation.status,'done');assert.deepEqual(a.foundation.steps.map(e=>e.actor),[builder.id,leader.id,leader.id,leader.id]);assert.equal(builder.health,40);assert.equal(builder.ailment,'лихорадка');exact(f);
});
test('without food or with an exhausted source, a ready body cannot reserve new material or initialize a settlement',()=>{
 const f=foundationFixture(),{s,a,g,builder}=f;g.cargo.food=0;foundationSteps(f,1);assert.equal(a.foundation,undefined);assert.equal(a.civic,undefined);assert.equal(builder.goodsRawCargo.quantity,4);assert.equal(builder.agenda.tools,1);g.cargo.food=9;a.forage.localFood.harvested+=a.forage.stock;a.forage.stock=0;foundationSteps(f,1);assert.equal(a.foundation,undefined);assert.equal(a.civic,undefined);exact(f);
});
test('resting at a temporary camp creates no foundation, while the finished food service gathers and carries actual local produce',()=>{
 const camp=foundationFixture({camp:true});foundationSteps(camp,2);assert.equal(camp.a.foundation,undefined);assert.equal(camp.a.civic,undefined);assert.equal(camp.g.status,'camped');exact(camp);
 const f=foundationSteps(foundationFixture(),4),{s,a,leader}=f,stock=a.forage.stock,food=a.civic.food;leader.agenda.task=null;leader.agenda.due=0;let steps=0;while(a.civic.food===food&&steps++<8){s.tick+=8;peopleTick(s,ctx);}assert.ok(steps<=8);assert.equal(a.forage.stock,stock-3);assert.equal(a.civic.food,food+6);assert.equal(a.goods.ledger.food.produced,0);assert.equal(a.goods.ledger.food.imported,food+6);assert.equal(leader.localFood.stock.mushroom,0);assert.equal(goodsBalance(a,'food').difference,0);exact(f);
});
test('duplicate body dispatch, a later area construction and reload do not repeat the house, title, founders or startup stock',()=>{
 const f=foundationFixture();foundationSteps(f,1);const r=f.a.foundation,progress=r.progress,food=f.g.cargo.food;peopleTick(f.s,ctx);assert.equal(r.progress,progress);assert.equal(f.g.cargo.food,food);foundationSteps(f,3);const id=f.a.foundedSettlement.id,people=Object.keys(f.s.people).length,raw=exact(f),stock=f.a.civic.food;const road=createArea(f.s,'road','Старая межа',0);initializeFacades(f.s);assert.ok(f.s.areas[road]);assert.equal(f.a.facades.profiles.length,1);assert.equal(f.a.foundedSettlement.id,id);assert.equal(f.a.civic.food,stock);assert.equal(Object.keys(f.s.people).length,people);assert.equal(serialize(restore(raw)),raw);foundationSteps(f,1);assert.equal(f.a.foundation.progress,4);assert.equal(f.g.cargo.food,0);assert.equal(f.a.objects.filter(o=>o.foundation===r.id).length,1);exact(f);
});
test('OFF pauses paid construction, death never revives the owner, and forged progress or missing foundation is rejected',()=>{
 const f=foundationSteps(foundationFixture(),1),{s,a,builder}=f;setModule(s,'migration-knowledge',false);const progress=a.foundation.progress,food=f.g.cargo.food;foundationSteps(f,1);assert.equal(a.foundation.progress,progress);assert.equal(f.g.cargo.food,food);exact(f);setModule(s,'migration-knowledge',true);builder.alive=false;builder.health=0;builder.status='dead';// Already deposited material remains physically on this site.
 // The food carrier is the living forager; no dead founder is needed for remaining work.
 foundationSteps(f,3);assert.equal(a.foundation.status,'done');assert.equal(builder.alive,false);assert.ok(!a.foundedSettlement.founders.includes(builder.id));assert.equal(a.foundation.tool.owner,builder.id);const raw=exact(f);
 for(const mutate of [w=>w.areas[a.id].foundation.material.remaining=1,w=>w.areas[a.id].foundation.steps[1].tick=w.areas[a.id].foundation.steps[0].tick,w=>delete w.areas[a.id].foundation]){const bad=JSON.parse(raw);mutate(bad);assert.throws(()=>restore(JSON.stringify(bad)),/foundation/);}
});
